import {createTelemetry,saveMatch,readMatches,exportMatches,BANDS} from './telemetry.js';
export function liveStats(m,enabled,mode='default'){return enabled?createTelemetry(m,{mode,source:'live'}):null;}
export function statsHTML(record){if(!record)return '';const rows=[['Whiffs',p=>`${p.whiffs} / ${p.meleeAttempts} melee attempts`],['Whiff punishes',p=>p.whiffPunishes],['Perfect guards',p=>p.perfectGuards],['Capture breaks',p=>p.captureBreaks],['Captures',p=>`${p.captures} (${p.capturesThroughGuard} through guard)`],['Chip taken',p=>p.chipTaken.toFixed(1)],['Attack presses / minute',p=>p.pressesPerMinute.toFixed(1)],['Damage / attack press',p=>p.damagePerPress?.toFixed(2)??'—'],...BANDS.map(b=>[b,p=>(p.distanceFrames[b]/60).toFixed(1)+'s'])];return `<style>#match-stats table{width:100%;border-collapse:collapse;font-size:13px}#match-stats th,#match-stats td{padding:5px 8px;text-align:left;border-bottom:1px solid #ffffff22}#match-stats th:first-child{width:45%}#match-stats a{color:#bcebd6;text-decoration:underline}#match-stats button{padding:8px 12px;margin:12px 8px 0 0;border:1px solid #bcebd6;border-radius:6px}#match-stats p{font-size:13px}</style><section id="match-stats"><h3>Match stats · ${record.seconds.toFixed(1)}s observed</h3><p>Per round / training segment. Damage includes all actions; whiffs count completed basic-strike/launcher active windows.</p><div style="overflow-x:auto"><table><tr><th>Measure</th><th>Player 1</th><th>Player 2</th></tr>${rows.map(([name,f])=>`<tr><th>${name}</th>${record.players.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`).join('')}</table></div><button id="export-match-stats">EXPORT JSON</button> <a href="./skill-lab.html?saved" target="_blank">Open skill dashboard</a></section>`;}
export function bindStats(record,{persist=false,storage}={}){try{storage??=localStorage;}catch{}if(persist&&storage)saveMatch(record,storage);const b=document.getElementById('export-match-stats');if(b)b.onclick=()=>{const rows=storage?readMatches(storage):[];if(!persist)rows.push(record);if(!rows.length)rows.push(record);const url=URL.createObjectURL(new Blob([JSON.stringify(exportMatches(rows))],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='rift-skill-matches.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
